def build_search_cases():
    # If S-GOLD-05 is added, ensure total cases count is calibrated
    # Replace S001 with S-GOLD-05 or keep exactly 100 cases
    cases_dict = {}
    for c in CASES:
        cases_dict[c["id"]] = c

    # Make sure we have exactly 100 cases by keeping S-GOLD-05 in place of S001 or as dedicated
    # Let's check length:
    final_cases = list(cases_dict.values())
    print(f"Total search cases: {len(final_cases)}")
    with open(OUT_FILE, "w", encoding="utf-8") as f:
        json.dump(final_cases, f, indent=2)
    print(f"Search cases saved to {OUT_FILE}")


if __name__ == "__main__":
    build_search_cases()
